-- Rollback-only qualification protocol tests with captured ENGINE-SHAPE fixture
-- responses. No provider is contacted and no genuine live qualification is claimed.
-- Only the NEW Stage17 qualification catalog helper is substituted to isolate
-- the accounting/issuer protocol; all changes, including issued fixture records,
-- are discarded by ROLLBACK. Existing model qualification is not manufactured.
begin;
create function pg_temp.expect_error(sql text, expected text default null) returns void language plpgsql as $$ begin
 begin execute sql; exception when others then
  if expected is not null and position(expected in sqlerrm)=0 then raise exception 'Unexpected error: %; wanted %',sqlerrm,expected; end if;
  return;
 end;
 raise exception 'Expected failure did not occur: %',sql;
end $$;
insert into auth.users(id,email) values('17000000-1111-4111-8111-000000000790','qualification-rollback@example.invalid'),('17000000-1111-4111-8111-000000000791','other-qualification-rollback@example.invalid');
insert into public.businesses(id,owner_user_id,name) values('17000000-1111-4111-8111-000000000002','17000000-1111-4111-8111-000000000790','Qualification rollback only'),('17000000-1111-4111-8111-000000000792','17000000-1111-4111-8111-000000000791','Other rollback only');
insert into private.etsy_server_authority values(private.stage13_hash(repeat('qualification-local-server-',3)),true);
select set_config('request.jwt.claim.sub','17000000-1111-4111-8111-000000000790',true);
do $$ begin
 assert not has_table_privilege('authenticated','private.listing_qualification_runs','SELECT');
 assert not has_table_privilege('authenticated','private.listing_live_qualifications','INSERT');
 assert not has_table_privilege('service_role','private.listing_qualification_settlements','INSERT');
 assert not has_function_privilege('authenticated','private.stage17_qualification_owner(uuid,text,jsonb,text)','EXECUTE');
 assert has_function_privilege('anon','public.listing_qualification_transition(uuid,uuid,text,text,jsonb)','EXECUTE');
 assert not private.stage17_qualification_attestation_current(gen_random_uuid());
 assert (select count(*)=0 from private.listing_live_qualifications);
 assert not private.stage17_qualified(), 'Synthetic teaching examples and owner grading are not live qualification';
end $$;
-- Adversarial owner-style Stage6 flags are deliberately forged inside a nested
-- rollback. They satisfy the legacy coarse helper but never the Stage17 gate.
do $$ declare wid uuid; sid uuid:=gen_random_uuid(); begin
 begin
  select id into strict wid from public.worker_definitions where worker_key='listing.specialist' and version='1.0.0';
  insert into public.worker_evaluation_suites(id,worker_definition_id,suite_key,version,name,description,minimum_score,require_all_required) values(sid,wid,'owner-forged-case','1.0.0','Forged owner flags','Adversarial rollback fixture only',0,false);
  insert into public.worker_evaluations(worker_definition_id,suite_id,requested_by,source,idempotency_key,status,score,subject_fingerprint,runtime_capability_hash,evidence) values(wid,sid,'17000000-1111-4111-8111-000000000790','owner','owner-forged-qualification','passed',100,private.stage6_worker_fingerprint(wid),repeat('a',64),'{"mode":"synthetic","mockProvider":true}');
  update public.worker_definitions set status='qualified' where id=wid;
  assert private.stage6_worker_is_currently_qualified(wid), 'Legacy helper accepts owner-authored passed flags';
  assert not private.stage17_qualified(), 'Owner/mock Stage6 promotion cannot mint private Stage17 authority';
  raise exception 'Rollback adversarial owner flags' using errcode='P7777';
 exception when sqlstate 'P7777' then null;
 end;
 assert (select count(*)=0 from private.listing_live_qualifications);
end $$;
set local role authenticated;
do $$ begin
 perform pg_temp.expect_error($q$select public.listing_owner_transition('17000000-1111-4111-8111-000000000792','start_qualification','{}')$q$,'owner_required');
 perform pg_temp.expect_error($q$select public.listing_owner_transition('17000000-1111-4111-8111-000000000002','start_qualification','{"approveModelCalls":true}')$q$,'server_authority_required');
 perform pg_temp.expect_error($q$select public.listing_qualification_transition('17000000-1111-4111-8111-000000000700','17000000-1111-4111-8111-000000000002',repeat('bad',12),'load')$q$,'listing_qualification_capability_denied');
 perform pg_temp.expect_error($q$insert into private.listing_qualification_runs(id) values(gen_random_uuid())$q$);
end $$;
reset role;
create temp table qualification_wire(data jsonb);
