 is printed to order by Printful, the declared production partner."}},{"id":"17000000-1111-4111-8111-000000000031","businessId":"17000000-1111-4111-8111-000000000002","recordId":"17000000-1111-4111-8111-000000000007","recordType":"creative_approval","verifiedAt":"2026-10-01T09:59:00.000Z","snapshotHash":"5d9cc1c5d5494a9ed557e89e584496413ea74e48d8c540312e731d4234be423e","snapshot":{"aiDesign":"The seller used AI tools to create the original fern illustration."}}],"facts":[{"id":"garment","statement":"A white cotton T-shirt with a green fern print on the front.","kind":"product","evidence":[{"sourceId":"17000000-1111-4111-8111-000000000030","pointer":"/garment"}]},{"id":"production","statement":"The seller''s design is printed to order by Printful, the declared production partner.","kind":"production","evidence":[{"sourceId":"17000000-1111-4111-8111-000000000030","pointer":"/production"}]},{"id":"ai-design","statement":"The seller used AI tools to create the original fern illustration.","kind":"rights","evidence":[{"sourceId":"17000000-1111-4111-8111-000000000031","pointer":"/aiDesign"}]}],"disclosures":[{"key":"production_partner","text":"Printed to order by our production partner, Printful.","factIds":["production"]},{"key":"ai","text":"This original illustration was created with the assistance of AI tools.","factIds":["ai-design"]}],"imagery":[{"assetId":"17000000-1111-4111-8111-000000000011","sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","productFactsHash":"7bb69721d7f6562b08a3c724981a86cfdc2f6f41267b9c2100171cab67da03a2","kind":"finished_product_mockup","finishedProductShown":true,"reviewArtifactId":"17000000-1111-4111-8111-000000000012","reviewedAt":"2026-10-01T09:59:30.000Z","altText":"Finished white cotton shirt with a green fern print","reviewResultHash":"17c9861882060f208a0a21f12b4278e92597485341b1b41eff0f139e80a3256a","reviewResult":{"businessId":"17000000-1111-4111-8111-000000000002","outcome":"PASS","observedProduct":"The supplied image is tightly cropped and does not resolve the exact garment, its white color, or the fern print placement. These PASS flags do not establish the finished product''s identity; a complete substantiated image review is missing.","productMatches":true,"finishedProductShown":true,"imageRightsVerified":true}}]},"proposal":{"version":"1.0.0","title":{"text":"Green Fern Print T-Shirt, White Cotton","factIds":["garment"]},"description":[{"text":"A green fern illustration is printed on the front of this white cotton T-shirt.","factIds":["garment"]}],"tags":[{"text":"fern shirt","factIds":["garment"]},{"text":"botanical tee","factIds":["garment"]}],"attributes":{"taxonomyId":482,"materials":["cotton"],"properties":[{"propertyId":100,"valueIds":[200],"values":["White"],"scaleId":null}]},"imageOrder":["17000000-1111-4111-8111-000000000011"],"disclosureKeys":["production_partner","ai"]},"proposalOrigin":"server_owned_test_case","testDataOnly":true,"evaluationTime":"2026-10-01T10:00:00.000Z"},"metadata":{"evidenceMode":"synthetic","qualificationTestData":true}},{"id":"5176d24d-f825-5b28-a7a7-45e307e7b554","artifactType":"knowledge.snapshot","name":"Etsy listing review","mediaType":"application/json","content":{"guidance":"Improve clarity using verified product facts; preserve applicable disclosures and image eligibility. Missing evidence stays unresolved.","attribution":"platform_rule paraphrases a stated Etsy requirement; guidance is advisory; implementation_inference is this application''s safeguard, not an Etsy rule.","guidelines":[{"id":"title-limit","kind":"platform_rule","sourceUrl":"https://help.etsy.com/hc/en-us/articles/115015628707-How-to-Create-a-Listing","statement":"Titles can contain at most 140 characters."},{"id":"tag-limits","kind":"platform_rule","sourceUrl":"https://help.etsy.com/hc/en-us/articles/360000336307-How-to-Use-Tags-to-Get-Found-in-Search","statement":"At most 13 tags, each at most 20 characters."},{"id":"clear-titles","kind":"guidance","sourceUrl":"https://www.etsy.com/seller-handbook/article/1399426136697","statement":"Name the product clearly with important factual traits first; avoid repetition, subjective praise, and price/shipping language. Fewer than 15 words is a suggestion, not a hard limit. Include occasions/recipients only when essential to the product."},{"id":"natural-description","kind":"guidance","sourceUrl":"https://www.etsy.com/seller-handbook/article/382774281517","statement":"Use relevant terms naturally in opening sentences, not a copied title or keyword list. Include useful product details and accurate descriptors; misleading material or other factual claims are unacceptable."},{"id":"relevant-tags-attributes","kind":"guidance","sourceUrl":"https://www.etsy.com/seller-handbook/article/382774281517","statement":"Prefer diverse multiword tags and a specific accurate category. Categories and attributes also help query matching, so avoid redundant exact-match tags. Do not invent claims just to fill 13 slots."},{"id":"supported-attributes","kind":"platform_rule","sourceUrl":"https://help.etsy.com/hc/en-us/articles/115014502508-How-to-Use-Attributes-When-Listing-an-Item","statement":"Available attributes depend on category. Material/material-feature claims must be accurate, not misleading, and supported by sufficient information; retain records and relevant certification support."},{"id":"image-eligibility","kind":"platform_rule","sourceUrl":"https://www.etsy.com/legal/policy/listing-image-requirements/253962679005","statement":"Use accurate finished-product photos with necessary image rights. A partner printing original artwork/patterns onto a base item permits a stock-photo mockup showing that end product. A uniquely designed physical item manufactured by a partner needs a real finished-product photo."},{"id":"personalized-lead-image","kind":"platform_rule","sourceUrl":"https://www.etsy.com/legal/policy/listing-image-requirements/253962679005","statement":"A personalized listing''s first image must show a real finished customized example similar to the offered item, not a blank or placeholder-text mockup. Additional mockups may illustrate customization options."},{"id":"image-order","kind":"guidance","sourceUrl":"https://www.etsy.com/seller-handbook/article/1347574487014","statement":"Use a clear first thumbnail; avoid overlays/collages there. Additional angles, detail, scale, and product-in-use images can inform buyers. Etsy does not prescribe this application''s exact image sequence."},{"id":"partner-disclosure","kind":"platform_rule","sourceUrl":"https://help.etsy.com/hc/en-us/articles/360000336547-Working-with-Production-Partners-on-Etsy","statement":"Disclose applicable production assistance on the listing and accurately represent shipping origin. Do not substitute invented partner details or location for missing evidence."},{"id":"ai-disclosure","kind":"platform_rule","sourceUrl":"https://www.etsy.com/legal/creativity/","statement":"Disclose in the listing description when the item was created using AI. Seller-prompted AI creations may qualify; eligibility still depends on applicable standards and rights."},{"id":"fact-bound-copy","kind":"implementation_inference","sourceUrl":"https://help.etsy.com/hc/en-us/articles/115014502508-How-to-Use-Attributes-When-Listing-an-Item","statement":"Every factual copy/attribute claim must trace to supplied verified evidence. Do not infer material, dimensions, care, variants, certification, origin, availability, delivery promises, or rights from artwork. Keep unresolved facts as needs-evidence; do not change immutable product terms."},{"id":"finished-product-evidence","kind":"implementation_inference","sourceUrl":"https://www.etsy.com/legal/policy/listing-image-requirements/253962679005","statement":"Never relabel a raw design PNG as a product mockup. Require reviewed image evidence bound to the actual asset and product facts and showing the finished product. An image plan, filename, or file format does not establish eligibility."},{"id":"adapter-image-bound","kind":"implementation_inference","sourceUrl":"https://help.etsy.com/hc/en-us/articles/115015628707-How-to-Create-a-Listing","statement":"This application''s Stage16 adapter accepts at most 10 reviewed images. This is an application bound, not Etsy''s platform maximum: the Help page retrieved for this snapshot says up to 20 photos."},{"id":"disclosure-preservation","kind":"implementation_inference","sourceUrl":"https://www.etsy.com/legal/creativity/","statement":"Preserve all applicable verified production-partner and AI disclosures. A draft paragraph is not proof the partner was configured or the item meets marketplace rules. AI-assisted copy alone is not evidence that the item was AI-created."},{"id":"bounded-review","kind":"implementation_inference","sourceUrl":"https://www.etsy.com/seller-handbook/article/382774281517","statement":"Schema validity is not semantic approval. Check factual support, image order and disclosures independently. No ranking, conversion, sales, profit, legal clearance, or readiness-to-publish promises; this snapshot grants no execution authority."}],"sources":[{"title":"How to Create a Listing","url":"https://help.etsy.com/hc/en-us/articles/115015628707-How-to-Create-a-Listing","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","dateStatus":"No publication/update date observed."},{"title":"New Guidance for Listing Titles","url":"https://www.etsy.com/seller-handbook/article/1399426136697","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","publishedUpdatedAt":"2026-04-27"},{"title":"Keywords 101","url":"https://www.etsy.com/seller-handbook/article/382774281517","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","publishedUpdatedAt":"2025-08-26"},{"title":"How to Use Tags to Get Found in Search","url":"https://help.etsy.com/hc/en-us/articles/360000336307-How-to-Use-Tags-to-Get-Found-in-Search","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","dateStatus":"No publication/update date observed."},{"title":"How to Use Attributes When Listing an Item","url":"https://help.etsy.com/hc/en-us/articles/115014502508-How-to-Use-Attributes-When-Listing-an-Item","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","dateStatus":"No publication/update date observed."},{"title":"The Anatomy of a Well-Crafted Etsy Listing","url":"https://www.etsy.com/seller-handbook/article/1347574487014","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","publishedUpdatedAt":"2025-08-26"},{"title":"Listing Image Requirements","url":"https://www.etsy.com/legal/policy/listing-image-requirements/253962679005","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","publishedUpdatedAt":"2024-07-09"},{"title":"Etsy''s Creativity Standards","url":"https://www.etsy.com/legal/creativity/","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","publishedUpdatedAt":"2025-06-10"},{"title":"Working with Production Partners on Etsy","url":"https://help.etsy.com/hc/en-us/articles/360000336547-Working-with-Production-Partners-on-Etsy","publisher":"Etsy","verifiedAt":"2026-10-01T09:54:00Z","dateStatus":"No publication/update date observed."}],"verification":{"method":"Public Etsy primary-source pages retrieved and reviewed; no accounts, providers, products, or market metrics inspected.","verifiedAt":"2026-10-01T09:54:00Z","interpretation":"Displayed article/update dates are not independently established effective dates. Keywords 101 also labels its advice as of August 2025. Undated Help pages are retrieval snapshots, not historical policy proof."},"sourceDateAnomaly":{"observedAt":"2026-10-01T09:54:00Z","displayedLastUpdated":"2026-10-05","excludedSourceUrls":["https://www.etsy.com/legal/sellers/","https://www.etsy.com/legal/fees/"],"note":"Both pages displayed future last-updated dates on this review. Exclude their current text as evidence of rules effective today; the mismatch remains unresolved. Reverify applicable versions before consequential use."},"limitations":["Thirty days is the maximum review interval, not a guarantee policies will remain unchanged. Reject stale or future-verified knowledge.","No specific listing, intellectual-property rights, physical sample, jurisdiction, cost, demand, or provider readback was verified. Advisory optimization is not promised performance."],"executionBoundary":"Bounded drafting and independent review only; no tool/provider calls, account changes, uploads, publishing, purchases, or spending are authorized by this knowledge."},"metadata":{"knowledgeKey":"etsy.listing-review","knowledgeVersion":"1.0.0","verifiedAt":"2026-10-01T09:54:00Z","source":"https://help.etsy.com/hc/en-us/articles/115015628707-How-to-Create-a-Listing"}}]}},"settle":{"caseKey":"reviewer_needs_image","reportedMicrousd":1000,"providerRequestId":"wire-only-qualified-reviewer_needs_image","receipt":{"version":"1.0.0","caseKey":"reviewer_needs_image","role":"reviewer","suiteHash":"c71239c53ae0c21be75a76b1cf0c19cd1048012850ad97265add785923ebfbf8","graderVersion":"listing-qualification-grader-1.0","executionMode":"listing.qualification","mockProvider":false,"requestedModel":"anthropic/claude-haiku-4.5","actualProviderModelId":"anthropic/claude-haiku-4.5","provider":"openrouter","upstreamProvider":"Anthropic","providerRequestId":"wire-only-qualified-reviewer_needs_image","reportedMicrousd":1000,"unknownCharge":false,"inputTokens":100,"outputTokens":100,"latencyMs":1,"finishReason":"stop","requestHash":"6b88aeea1d95d0eea1bcb9a174ce94f163532627fb7ca8fe6dabe624a6c4daa3","transportRequestHash":"942a65f7e1331c6a4b97ce5c9fefb9ace58f9267905cb59ef5ceabcb34763a2a","outputValidated":true,"casePassed":true,"outputHash":"0e7ca16ac3a86d7c91b4570cca9f837df301547a9dd240f48c5f17dccf8def99","completedAt":"2026-10-01T11:13:56.571Z"}},"persist":{"caseKey":"reviewer_needs_image","output":{"version":"1.0.0","verdict":"NEEDS_EVIDENCE","checks":{"title":{"status":"passed","rationale":"The title identifies the white cotton shirt and fern print supported by garment."},"description":{"status":"passed","rationale":"The paragraph describes only the garment and front print in the verified product fact."},"tags":{"status":"passed","rationale":"Both tags describe the documented fern shirt without unsupported audience or material claims."},"attributes":{"status":"passed","rationale":"Category, cotton material and White property exactly preserve the approved product snapshot."},"imageOrder":{"status":"needs_evidence","rationale":"The cropped image cannot establish the exact finished garment or fern placement; a complete product review is missing."},"disclosures":{"status":"passed","rationale":"The description includes both exact production-partner and AI-item disclosures from the facts."},"factualClaims":{"status":"passed","rationale":"Every copy unit is entailed by garment; no shipping, certification, sales or rights promise was added."}}}}}]}'::jsonb);
-- Isolate the new protocol without rewriting any older qualification function.
create or replace function private.stage17_qualification_catalog(p_knowledge_hash text,p_worker_hashes jsonb) returns jsonb language sql set search_path='' as $$
 select (select jsonb_object_agg(replace(p.pack_key,'worker.listing-',''),jsonb_build_object('workerDefinitionId',d.id,'workerFingerprint',private.stage6_worker_fingerprint(d.id),'manifest',p.manifest->'workers'->0->'manifest','pack',p.manifest)) from public.packs p join public.worker_definitions d on d.pack_id=p.id where p.pack_key in ('worker.listing-specialist','worker.listing-reviewer'))||jsonb_build_object('knowledge',(select manifest->'knowledge'->0 from public.packs where pack_key='knowledge.etsy-listing-review'));
$$;
create function pg_temp.seed_qualification(n integer,p_expires timestamptz default clock_timestamp()+interval '1 hour') returns uuid language plpgsql as $$
declare rid uuid:=case when n=1 then '17000000-1111-4111-8111-000000000700'::uuid else private.stage4_deterministic_uuid('qualification-test:'||n) end; wid uuid:=private.stage4_deterministic_uuid('qualification-workflow:'||n); state jsonb; suite jsonb:=private.stage17_qualification_suite();
begin
 select data->'state' into state from qualification_wire;
 insert into private.listing_mutation_admissions values(txid_current());
 insert into public.workflow_runs(id,business_id,workflow_definition_id,status,current_stage_key,idempotency_key) select wid,'17000000-1111-4111-8111-000000000002',id,'running','qualification','qualification-test:'||n from public.workflow_definitions where workflow_key='etsy.listing-qualification';
 insert into private.listing_qualification_runs(id,business_id,owner_id,workflow_run_id,suite_hash,knowledge_hash,worker_hashes,catalog_snapshot,quote,maximum_microusd,capability_hash,launch_nonce,expires_at,status)
  values(rid,'17000000-1111-4111-8111-000000000002','17000000-1111-4111-8111-000000000790',wid,suite->>'suiteHash',suite->>'knowledgeHash',suite->'workerHashes',private.stage17_qualification_catalog(suite->>'knowledgeHash',suite->'workerHashes'),jsonb_set(state->'quote','{verifiedAt}',to_jsonb(clock_timestamp()::text)),1000000,private.stage13_hash(repeat('qualification-local-cap-',3)),gen_random_uuid(),p_expires,'running');
 delete from private.listing_mutation_admissions where transaction_id=txid_current();return rid;
end $$;
create function pg_temp.qualification_reserve(rid uuid,k text) returns jsonb language plpgsql as $$
declare payload jsonb; c jsonb; tid uuid:=private.stage4_deterministic_uuid('listing:qualification:task:'||rid||':'||k); dataid uuid:=private.stage4_deterministic_uuid('listing:knowledge:'||tid);
begin
 select v->'reserve' into strict payload from qualification_wire,jsonb_array_elements(data->'calls') v where v->'reserve'->>'caseKey'=k;
 select value into strict c from jsonb_array_elements(private.stage17_qualification_suite()->'cases') where value->>'key'=k;
 -- These exact context paths are the only task-scoped fields in the captured engine shape.
 payload:=jsonb_set(payload,'{context}',jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(c->'context','{taskContract,id}',to_jsonb(tid::text)),'{taskContract,inputArtifactIds,0}',to_jsonb(dataid::text)),'{taskContract,inputArtifactIds,1}',to_jsonb(tid::text)),'{inputArtifacts,0,id}',to_jsonb(dataid::text)),'{inputArtifacts,1,id}',to_jsonb(tid::text)));
 return jsonb_set(payload,'{estimate,quote,verifiedAt}',to_jsonb(clock_timestamp()::text));
end $$;
create function pg_temp.qualification_settle(rid uuid,k text,charge bigint default 1000,passed boolean default true) returns jsonb language plpgsql as $$
declare payload jsonb;
begin
 select v->'settle' into strict payload from qualification_wire,jsonb_array_elements(data->'calls') v where v->'settle'->>'caseKey'=k;
 payload:=jsonb_set(jsonb_set(jsonb_set(payload,'{reportedMicrousd}',coalesce(to_jsonb(charge),'null'::jsonb)),'{providerRequestId}',to_jsonb(rid||':'||k)),'{receipt,providerRequestId}',to_jsonb(rid||':'||k));
 payload:=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{receipt,reportedMicrousd}',coalesce(to_jsonb(charge),'null'::jsonb)),'{receipt,unknownCharge}',to_jsonb(charge is null)),'{receipt,outputValidated}',to_jsonb(passed)),'{receipt,casePassed}',to_jsonb(passed));
 return jsonb_set(payload,'{receipt,completedAt}',to_jsonb(clock_timestamp()::text));
end $$;
create function pg_temp.qualification_persist(k text) returns jsonb language sql as $$
 select v->'persist' from qualification_wire,jsonb_array_elements(data->'calls') v where v->'persist'->>'caseKey'=k;
$$;
